17	        this.code = code;
18	    }
19	
20	    public HttpStatus getStatus() {
21	        return status;
22	    }
23	
24	    public String getCode() {
25	        return code;
26	    }
27	
28	    /** 400：参数非法。 */
29	    public static ApiException badRequest(String message) {
30	        return new ApiException(HttpStatus.BAD_REQUEST, "BAD_REQUEST", message);
31	    }
