86	    @Test
87	    void revokeAndReleaseConcurrentFollowCommitOrder() throws Exception {
88	        // 重复多轮，验证任意调度下都不出现“撤销后仍被放行”
89	        for (int round = 0; round < 15; round++) {
90	            final int r = round;
91	            String certBody = mvc.perform(post("/api/certificates")
92	                            .contentType(MediaType.APPLICATION_JSON)
93	                            .content("""
94	                                    {"instrumentId":"INS-R%d","validFrom":"2026-01-01T00:00:00Z",
95	                                     "validTo":"2028-01-01T00:00:00Z","a":"1","b":"0"}""".formatted(r)))
96	                    .andReturn().getResponse().getContentAsString();
97	            long certId = ((Number) com.jayway.jsonpath.JsonPath.read(certBody, "$.id")).longValue();
98	
99	            mvc.perform(post("/api/measurements")
100	                    .contentType(MediaType.APPLICATION_JSON)
101	                    .content("""
102	                            {"measurementKey":"M-%d","instrumentId":"INS-R%d",
103	                             "measuredAt":"2026-06-01T00:00:00Z","reading":"1",
104	                             "lowerLimit":"0","upperLimit":"9","submittedBy":"alice"}""".formatted(r, r)))
105	                    .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isCreated());
106	
107	            ExecutorService pool = Executors.newFixedThreadPool(2);
108	            CountDownLatch start = new CountDownLatch(1);
109	            Future<Integer> revokeFuture = pool.submit(() -> {
110	                start.await();
111	                return mvc.perform(post("/api/certificates/{id}/revoke", certId))
112	                        .andReturn().getResponse().getStatus();
113	            });
114	            Future<Integer> releaseFuture = pool.submit(() -> {
115	                start.await();
116	                return mvc.perform(post("/api/measurements/release")
117	                                .header("X-Actor-Id", "carol")
118	                                .contentType(MediaType.APPLICATION_JSON)
119	                                .content("{\"keys\":[\"M-" + r + "\"]}"))
120	                        .andReturn().getResponse().getStatus();
121	            });
122	            start.countDown();
123	            int revokeStatus = revokeFuture.get(30, TimeUnit.SECONDS);
124	            int releaseStatus = releaseFuture.get(30, TimeUnit.SECONDS);
125	            pool.shutdown();
126	            assertEquals(200, revokeStatus);
127	            assertTrue(releaseStatus == 200 || releaseStatus == 409);
128	
129	            Map<String, Object> cert = jdbc.queryForMap("SELECT * FROM calibration_certificate WHERE id = ?", certId);
130	            Map<String, Object> measurement = jdbc.queryForMap(
131	                    "SELECT * FROM measurement WHERE measurement_key = ?", "M-" + r);
132	            Integer releaseCount = jdbc.queryForObject(
133	                    "SELECT COUNT(*) FROM release_record WHERE measurement_id = ?",
134	                    Integer.class, ((Number) measurement.get("id")).longValue());
135	
136	            if (releaseCount > 0) {
