 * @param invalidationKey 失效单业务键
 * @param confirmedBy     确认人（质量人员）
 * @param confirmedAt     确认时间（UTC）
 */
public record InvalidationConfirmation(
        long id,
        String invalidationKey,
        String confirmedBy,
        Instant confirmedAt) {
}

