    /** 失效冻结未审核：失效单激活时仍处于待放行，被标记为阻塞，不得再放行。 */
    BLOCKED,

    /** 失效冻结待复审：失效单激活时已放行，状态改为待复审；原放行快照与数值保留。 */
    REVIEW_REQUIRED
}

